INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20301, 'Ezekiel 37:19', 'Ezekiel', 37, 19, '&nbsp;هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به د يوسف امسا راواخلم کومه چې د اِفرائيم په لاس کښې ده او د بنى اِسرائيلى قبيلو سره ده چې دۀ سره يې اِتحاد دے او دا د يهوداه امسا سره يو ځائ کوم، او د هغوئ نه يوه امسا جوړوم. او هغه دواړه به زما په لاس کښې يو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20302, 'Ezekiel 37:20', 'Ezekiel', 37, 20, '&nbsp;نو په کومو امساګانو دې چې ليکل وکړل د هغه خلقو د سترګو د وړاندې يې ونيسه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20303, 'Ezekiel 37:21', 'Ezekiel', 37, 21, '&nbsp;او هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به بنى اِسرائيل د هغه قومونو د مينځ نه راوکاږم چرته چې هغوئ تللى دى. زۀ به هغوئ د هرې خوا نه رايوځائ کړم او هغوئ به خپل مُلک ته واپس راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20304, 'Ezekiel 37:22', 'Ezekiel', 37, 22, '&nbsp;زۀ به د بنى اِسرائيلو په مُلک او د بنى اِسرائيلو په غرونو کښې د هغوئ نه يو قوم جوړ کړم. په هغوئ ټولو به يو بادشاه حکومت کوى او هغوئ به بيا هيڅکله نۀ دوه قومونه شى او نۀ به په دوو بادشاهتونو تقسيم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20305, 'Ezekiel 37:23', 'Ezekiel', 37, 23, '&nbsp;هغوئ به نور خپل ځانونه نۀ پليتوى په خپلو بُتانو او نۀ په بدو شکلونو او نۀ په خپلو نورو ګناهونو باندې، ځکه چې زۀ به هغوئ د خپلو ناروا واپس کېدو نۀ وساتم، او زۀ به هغوئ پاک کړم. هغوئ به زما خلق وى او زۀ به د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20306, 'Ezekiel 37:24', 'Ezekiel', 37, 24, '&nbsp;زما خِدمتګار داؤد به د هغوئ بادشاه او د هغوئ ټولو به يو شپونکے وى. هغوئ به زما په اصُولو عمل کوى او زما د قانون د منلو به ډېر خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20307, 'Ezekiel 37:25', 'Ezekiel', 37, 25, '&nbsp;هغوئ به په هغه مُلک کښې اوسيږى کوم چې ما خپل خِدمتګار يعقوب له ورکړے دے، هغه مُلک چې په کښې ستاسو پلار نيکۀ اوسېدل. هغوئ او د هغوئ ماشومان به نسل در نسل په دې کښې د تل دپاره اوسيږى، او داؤد زما خِدمتګار به د تل دپاره د هغوئ شهزاده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20308, 'Ezekiel 37:26', 'Ezekiel', 37, 26, '&nbsp;زۀ به د هغوئ سره د امن يو لوظ وکړم، او دا به ابدى لوظ وى. زۀ به هغوئ په خپل مُلک کښې آباد کړم او د هغوئ شمېر به زيات کړم، او زۀ به د هغوئ په مينځ کښې خپله مقدسه عبادتګاه د تل دپاره جوړه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20309, 'Ezekiel 37:27', 'Ezekiel', 37, 27, '&nbsp;زما د اوسېدو ځائ به د هغوئ سره وى، زۀ به د هغوئ خُدائ پاک يم، او هغوئ به زما خلق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20310, 'Ezekiel 37:28', 'Ezekiel', 37, 28, '&nbsp;نو بيا قومونه به په دې پوهه شى چې ما مالِک خُدائ بنى اِسرائيل مقدس کړل، کله چې زما مقدسه عبادتګاه د تل دپاره د هغوئ په مينځ کښې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20311, 'Ezekiel 38:1', 'Ezekiel', 38, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20312, 'Ezekiel 38:2', 'Ezekiel', 38, 2, '&nbsp;”اے بنى آدمه، خپل مخ د ماجوج د مُلک د جوج خلاف کړه، د مسک او توبل د لوئ شهزاده، په خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20313, 'Ezekiel 38:3', 'Ezekiel', 38, 3, '&nbsp;او ورته ووايه، مالِک قادر مطلق خُدائ دا فرمائى چې، اے جوجه د مسک او توبل لوئ شهزاده زۀ ستاسو خلاف يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20314, 'Ezekiel 38:4', 'Ezekiel', 38, 4, '&nbsp;زۀ به تا ته راوګرځوم، او په ژامنو کښې به دې کُنډې واچوم او د خپل ټول فوج او آسونو سره به دې بهر راوکاږم، ستا د آسونو سوارۀ په زغرو سمبال دى، او يو لوئ لښکر د خپلو وړو او غټو ډالونو سره دے، او هغوئ ټولو خپلې تُورى راويستلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20315, 'Ezekiel 38:5', 'Ezekiel', 38, 5, '&nbsp;د فارس، ايتهوپيا او ليبيا خلق به تا سره شى، او دوئ سره به خپل ډالونه او جنګى ټوپۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20316, 'Ezekiel 38:6', 'Ezekiel', 38, 6, '&nbsp;جُمر به هم سره د خپل ټول لښکر تا سره وى، او د شمال د لرې ځائ بيت‌تُجرمه به خپل ټول لښکر سره او نور ډېر قومونه به تا سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20317, 'Ezekiel 38:7', 'Ezekiel', 38, 7, '&nbsp;تۀ تيار شه، تيار اوسه، ټول لښکر چې تا ته د خوا او شا نه راغونډ شوے دے د هغې مشرى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20318, 'Ezekiel 38:8', 'Ezekiel', 38, 8, '&nbsp;ډيرې ورځې وروستو به تا ته حکم وشى چې مسلح شه. په راتلونکى کالونو کښې به تۀ په يو داسې مُلک حمله وکړې کوم چې د جنګ نه په آرام شوے دے، د چا خلق چې د ډېرو مُلکونو نه د بنى اِسرائيلو غرونو ته راغونډ شوى دى، کوم مُلک چې د ډيرې مودې نه وران وو. هغوئ د هغه مُلکونو نه راوستلے شوى دى، او اوس هغوئ ټول په امن کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20319, 'Ezekiel 38:9', 'Ezekiel', 38, 9, '&nbsp;تۀ او ستا ټول لښکر او هغه ډېر قومونه چې تا سره دى به ورمخکښې شى، لکه د طوفان په شان حمله به وکړى، او تاسو به لکه د وريځې په شان په هغه مُلک کښې خوارۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20320, 'Ezekiel 38:10', 'Ezekiel', 38, 10, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، په هغه ورځ به ستا ذهن کښې بد خيالونه راشى او تۀ به غلطه منصوبه جوړه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20321, 'Ezekiel 38:11', 'Ezekiel', 38, 11, '&nbsp;تۀ به ووائې چې، زۀ به په هغه مُلک حمله وکړم چې دېوالونه يې نۀ وى، زۀ به په هغه خلقو باندې حمله وکړم چې پُراَمنه او په آرام ژوند کوى، هغوئ ټول بغېر د دېوالونو او دروازو او کُنډو اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20322, 'Ezekiel 38:12', 'Ezekiel', 38, 12, '&nbsp;زۀ به لوټ مار جوړ کړم او خپل لاس به بيا ودان شوو کنډرو پسې او د هغه خلقو خلاف کړم چې د ډېرو قومونو نه راغونډ شوى دى، هغوئ اوس د څاروو او سامانونو نه مالا مال دى، او د دُنيا په مينځ کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20323, 'Ezekiel 38:13', 'Ezekiel', 38, 13, '&nbsp;د شيبا او د ددان او د ترسيس سوداګر او د دې ټول کليوال به تا ته وائى، ولې تۀ لوټ کولو له راغلے يې څۀ؟ ولې تا خپل لښکر د دې دپاره راغونډ کړے دے چې لوټ مار وکړى، سپين زر او سرۀ زر يوسى، چې څاروى او سامانونه يوسى او ډېر مال لوټ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20324, 'Ezekiel 38:14', 'Ezekiel', 38, 14, '&nbsp;نو په دې وجه، اے بنى آدمه، پېشګوئې وکړه او جوج ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې په هغه ورځ، کله چې زما خلق بنى اِسرائيل په امن اوسيږى ولې تۀ به دا نۀ ګورې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20325, 'Ezekiel 38:15', 'Ezekiel', 38, 15, '&nbsp;تۀ به د خپل لرې ځائ شمال نه راشې، تۀ او ډېر قومونه به درسره وى، هغوئ ټول به په آسونو سوارۀ وى، يو لوئ لښکر، او تکړه فوج به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20326, 'Ezekiel 38:16', 'Ezekiel', 38, 16, '&nbsp;تۀ به زما د قوم بنى اِسرائيلو خلاف لکه د وريځ حمله وکړې کومه چې زمکه پټوى. په راتلونکو ورځو کښې، اے جوجه، زۀ به تا د خپل مُلک په خلاف راپاڅوم، نو چې مُلکونه ما وپېژنى کله چې ستا په وسيله زۀ خپل ځان د هغوئ د سترګو د وړاندې مقدس ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20327, 'Ezekiel 38:17', 'Ezekiel', 38, 17, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى، ولې تۀ هم هغه نۀ يې د چا چې ما ډېر پخوا د خپلو خِدمتګارانو د بنى اِسرائيلو د پېغمبرانو په وسيله خبرې کړې وې؟ په هغه وخت کښې هغوئ تر ډېرو کالونو پورې پېشګوئې وکړه چې زۀ به تا د هغوئ خلاف راولم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20328, 'Ezekiel 38:18', 'Ezekiel', 38, 18, '&nbsp;”په هغه ورځ به داسې وشى، کله چې جوج د اِسرائيل په مُلک حمله وکړى، زما سخت قهر به راوپاريږى، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20329, 'Ezekiel 38:19', 'Ezekiel', 38, 19, '&nbsp;زۀ په خپل غېرت او سخت قهر کښې دا فرمايم چې په هغه ورځ به د اِسرائيل په مُلک کښې يوه لويه زلزله راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20330, 'Ezekiel 38:20', 'Ezekiel', 38, 20, '&nbsp;د سمندر کبان، د هوا مارغان، د صحرا ځناور، هر يو مخلوق کوم چې په زمکه باندې ګرځى، او د زمکې په مخ باندې ټول انسانان به زما په حضور کښې ولړزيږى. غرونه به اولټه شى، د غرونو څوکې به راونړيږى او هر يو دېوال به په زمکه راپرېوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20331, 'Ezekiel 38:21', 'Ezekiel', 38, 21, '&nbsp;زۀ به تُوره د جوج خلاف په خپلو ټولو غرونو ورولېږم مالِک قادر مطلق خُدائ فرمائى. د هر چا تُوره به د خپل ورور خلاف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20332, 'Ezekiel 38:22', 'Ezekiel', 38, 22, '&nbsp;زۀ به په وبا او قتل عام د هغۀ عدالت وکړم، زۀ به سېلابى بارانونه، ږلۍ او سوزونکى ګوګړ په هغۀ او د هغۀ په لښکرو او ورسره په نورو ډېرو قومونو نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20333, 'Ezekiel 38:23', 'Ezekiel', 38, 23, '&nbsp;او بيا به زۀ خپله لوئى او پاکوالے ښکاره کړم، او زۀ به خپل ځان د ډېرو قومونو په وړاندې ښکاره کړم. بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20334, 'Ezekiel 39:1', 'Ezekiel', 39, 1, '&nbsp;”اے بنى آدمه، د جوج خلاف پېشګوئې وکړه او ورته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى، اے جوجه، د مسک او توبل لوئ شهزاده زۀ ستا خلاف يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20335, 'Ezekiel 39:2', 'Ezekiel', 39, 2, '&nbsp;زۀ به تا راتاو کړم او رابه دې کاږم. زۀ به تا د شمال لرې ځائ نه راولم او د بنى اِسرائيلو د غرونو خلاف به دې ولېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20336, 'Ezekiel 39:3', 'Ezekiel', 39, 3, '&nbsp;بيا به زۀ لينده ستا د ګس لاس نه واخلم او غشى به ستا د ښى لاس نه وغورزوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20337, 'Ezekiel 39:4', 'Ezekiel', 39, 4, '&nbsp;د بنى اِسرائيلو په غرونو به تۀ سره د خپلو ټولو فوجيانو او ټولو قومونو چې تا سره دى قتل کړے شې. زۀ به تاسو د هر قسمه مردار خورو مارغانو او ځنګلى ځناورو په خوراک بدل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20338, 'Ezekiel 39:5', 'Ezekiel', 39, 5, '&nbsp;تاسو به په هوار مېدان کښې قتل شئ، ځکه چې دا ما مالِک قادر مطلق خُدائ فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20339, 'Ezekiel 39:6', 'Ezekiel', 39, 6, '&nbsp;زۀ به په ماجوج او په هغوئ څوک چې د سمندر په غاړه کښې په امن اوسيږى اور نازل کړم، او هغوئ به په دې پوهه شى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20340, 'Ezekiel 39:7', 'Ezekiel', 39, 7, '&nbsp;زۀ به خپل مقدس نوم د خپلو خلقو بنى اِسرائيلو په مينځ کښې څرګند کړم. زۀ به نور خپل مقدس نوم بې‌حرمتۍ ته پرې نۀ ږدم، او قومونه به پوهه شى چې زۀ مالِک خُدائ په بنى اِسرائيلو کښې مقدس ذات يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20341, 'Ezekiel 39:8', 'Ezekiel', 39, 8, '&nbsp;دا ورځ راروانه ده، دا به يقيناً راشى، مالِک قادر مطلق خُدائ دا فرمائى. دا هغه ورځ ده چې ما يې ذکر کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20342, 'Ezekiel 39:9', 'Ezekiel', 39, 9, '&nbsp;بيا هغوئ څوک چې د بنى اِسرائيلو په ښارونو کښې اوسيږى به بهر لاړ شى او وسلې به د سوزولو دپاره استعمال کړى او واړۀ او غټ ډالونه، ليندې او غشى، جنګى ډنډې او نېزې به وسوزوى. د اووۀ کالو پورې به هغوئ دا سوزولو دپاره استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20343, 'Ezekiel 39:10', 'Ezekiel', 39, 10, '&nbsp;هغوئ ته به ضرورت نۀ وى د پټو نه د خشاک راټولولو او نۀ به ورته د ځنګل د کټ کولو، ځکه چې هغوئ به وسلې د خشاک په طور استعمال کړى. او هغوئ به هغه لوټ کړى چا چې دوئ لوټ کړى وُو او هغوئ به تالا کړى چا چې دوئ تالا کړى وُو، مالِک قادر مطلق خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20344, 'Ezekiel 39:11', 'Ezekiel', 39, 11, '&nbsp;”په هغه ورځ به زۀ جوج له په بنى اِسرائيلو کښې د يو لوئ قبرستان ځائ ورکړم، په هغه وادۍ کښې په کومه کښې چې خلق د سمندر مشرق خوا ته تلۀ راتلۀ کوى. دا به د مسافرو لاره بنده کړى، ځکه چې جوج او د هغۀ ټول لښکر به هلته ښخ وى. نو بيا به دې ته د هامون جوج وادى وئيلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20345, 'Ezekiel 39:12', 'Ezekiel', 39, 12, '&nbsp;تر اوو مياشتو پورې به د بنى اِسرائيلو قوم هغوئ ښخوى د دې دپاره چې زمکه ترې صفا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20346, 'Ezekiel 39:13', 'Ezekiel', 39, 13, '&nbsp;د هغه مُلک ټول خلق به د هغوئ په ښخولو کښې مدد وکړى، په دې ورځ چې زۀ په دُنيا باندې خپل جلال څرګند کړم، نو دا کار به د دوئ دپاره د عزت باعث شى، مالِک قادر مطلق خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20347, 'Ezekiel 39:14', 'Ezekiel', 39, 14, '&nbsp;د مُلک پاکولو دپاره به کسان لګولے شوى وى چې هغه صفا کړى. او د هغوئ سره څۀ کسان به په ټول مُلک کښې وګرځى او نور لاشونه چې په زمکه پاتې وى چې هغه ښخ کړى. او پوره اووۀ مياشتې به هغوئ خپل لټون جارى وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20348, 'Ezekiel 39:15', 'Ezekiel', 39, 15, '&nbsp;کله چې هغوئ په ټول مُلک کښې ګرځى او په هغوئ کښې يو کس د انسان هډوکى وګورى، نو هغه به د دې په خوا کښې نښه جوړه کړى ترڅو چې قبرکند هغه د هامون جوج په وادۍ کښې ښخ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20349, 'Ezekiel 39:16', 'Ezekiel', 39, 16, '&nbsp;هلته يو ښار هم دے چې هامونه نوميږى. نو دغه شان به هغوئ زمکه پاکه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20350, 'Ezekiel 39:17', 'Ezekiel', 39, 17, '&nbsp;اے بنى آدمه، مالِک قادر مطلق خُدائ دا فرمائى چې، هر قسمه مارغانو او ځناورو ته آواز وکړئ چې، راجمع شئ او د ټولو ګېرچاپېره ځايونو نه هغه قربانۍ دپاره راشئ چې زۀ يې تاسو دپاره تياروم، دا د بنى اِسرائيلو په غرونو لويه قربانى ده. هلته به تاسو غوښې وخورئ او وينه به وڅښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20351, 'Ezekiel 39:18', 'Ezekiel', 39, 18, '&nbsp;تاسو به د تکړه سړو غوښې وخورئ او د زمکې د شهزادګانو وينې به وڅښئ، دوئ ټول لکه د بسن د ګډانو او ګډورو، چېلو او غوَيانو، څاربۀ څاروى په شان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20352, 'Ezekiel 39:19', 'Ezekiel', 39, 19, '&nbsp;کومه قربانى چې زۀ تاسو دپاره تياروم، د دې چربى به تاسو په مَړه خېټه وخورئ او وينه به تر هغې وڅښئ چې نشه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20353, 'Ezekiel 39:20', 'Ezekiel', 39, 20, '&nbsp;زما په دسترخوان به تاسو د آسونو او د آسونو د سورو، د تکړه سړو، او د هر قسم فوجيانو غوښې وخورئ، مالِک قادر مطلق خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20354, 'Ezekiel 39:21', 'Ezekiel', 39, 21, '&nbsp;زۀ به د قومونو په مينځ کښې خپل جلال ښکاره کړم، او ټول قومونه به وګورى هغه سزا چې زۀ يې نازلوم او هغه لاس چې ما په هغوئ باندې اېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20355, 'Ezekiel 39:22', 'Ezekiel', 39, 22, '&nbsp;د هغه ورځې نه به بنى اِسرائيل په دې پوهه شى چې زۀ مالِک خُدائ د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20356, 'Ezekiel 39:23', 'Ezekiel', 39, 23, '&nbsp;او قومونه به په دې پوهه شى چې بنى اِسرائيل د خپلې ګناه په وجه جلاوطن کړے شوى وُو، ځکه چې هغوئ ما سره بې‌وفا وُو. نو ځکه ما خپل مخ د هغوئ نه پټ کړو او هغوئ مې دشمنانو ته حواله کړل، او په تُوره باندې قتل کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20357, 'Ezekiel 39:24', 'Ezekiel', 39, 24, '&nbsp;ما د هغوئ سره د هغوئ د ناپاکوالى او د بدعملۍ په مطابق سلوک وکړو، او ما خپل مخ د هغوئ نه پټ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20358, 'Ezekiel 39:25', 'Ezekiel', 39, 25, '&nbsp;”نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى، زۀ به اوس يعقوب د غلامۍ نه واپس راولم او د اِسرائيل په ټولو خلقو به رحم وکړم، او زۀ به په خپل مقدس نوم غېرت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20359, 'Ezekiel 39:26', 'Ezekiel', 39, 26, '&nbsp;هغوئ به خپل شرم او هغه ټوله بې‌ايمانى هېره کړى کومه چې هغوئ زما خلاف کړې وه کله چې هغوئ په خپل مُلک کښې بغېر د چا د يرې نه په امن او سکون کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20360, 'Ezekiel 39:27', 'Ezekiel', 39, 27, '&nbsp;کله چې زۀ هغوئ د نورو قومونو نه واپس راولم او هغوئ د خپلو دشمنانو د مُلکونو نه راغونډ کړم، نو زۀ به خپل ځان د نورو ډېرو قومونو د سترګو په وړاندې د دوئ په وسيله مقدس ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20361, 'Ezekiel 39:28', 'Ezekiel', 39, 28, '&nbsp;نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ د هغوئ خُدائ پاک يم، اګر کۀ ما هغوئ نورو مُلکونو ته جلاوطن کړى وُو، زۀ به هغوئ خپل مُلک ته رايوځائ کړم، او د هغوئ يو کس به هم وروستو پرې نۀ ږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20362, 'Ezekiel 39:29', 'Ezekiel', 39, 29, '&nbsp;زۀ به نور هيڅکله خپل مخ د دوئ نه پټ نۀ کړم، زۀ به خپل روح د بنى اِسرائيلو په قوم نازل کړم، مالِک قادر مطلق خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20363, 'Ezekiel 40:1', 'Ezekiel', 40, 1, '&nbsp;زمونږ د جلاوطنۍ په پينځويشتم کال، د څوارلسم کال په شروع کېدو او د مياشتې په لسم تاريخ چې ښار راپرېوتو په هم دغه ورځ د مالِک خُدائ لاس په ما باندې وو او هغۀ زۀ هلته بوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20364, 'Ezekiel 40:2', 'Ezekiel', 40, 2, '&nbsp;د مالِک خُدائ په رويا کښې هغۀ زۀ د بنى اِسرائيلو مُلک ته بوتلم. او د يو ډېر اوچت غر دپاسه يې کښېنولم، د چا په جنوب طرف کښې چې يو څو عمارتونه وُو کوم چې د يو ښار په شان ښکارېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20365, 'Ezekiel 40:3', 'Ezekiel', 40, 3, '&nbsp;کله چې هغۀ زۀ هلته بوتلم، نو ما يو سړے وليدو څوک چې د زېړو په شان ښکارېدو، او هغه د دروازې په خولۀ کښې ولاړ وو او په لاس کښې يې د کتان فيته وه او د ناپ تول لرګے يې نيولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20366, 'Ezekiel 40:4', 'Ezekiel', 40, 4, '&nbsp;هغه سړى ما ته ووئيل، ”اے بنى آدمه، په خپلو سترګو وګوره او په خپلو غوږونو واوره او هر څۀ چې درته ښايم هغې ته ښۀ توجو وکړه، ځکه خو تۀ د دې دپاره راوستلے شوے يې. هر څۀ چې تۀ ووينې هغه د بنى اِسرائيلو قوم ته ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20367, 'Ezekiel 40:5', 'Ezekiel', 40, 5, '&nbsp;ما وليدل چې هلته د مالِک خُدائ د کور نه ګېرچاپېره دېوال راتاو وو. د هغه سړى په لاس کښې د ناپ کولو لرګے لس نيم فټه وو چې دېوال يې ناپ کړو، او دېوال غټوالے لس نيم فټه پلن وو او لس نيم فټه اوچت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20368, 'Ezekiel 40:6', 'Ezekiel', 40, 6, '&nbsp;نو بيا هغه د هغې دروازې خوا ته لاړو چې مخ يې د مشرق طرف ته وو. هغه په پوړو وروختو او د دروازې درشل يې ناپ کړو چې هغه لس نيم فټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20369, 'Ezekiel 40:7', 'Ezekiel', 40, 7, '&nbsp;هلته په دروازه کښې ښې طرف ته او ګس طرف ته درې د څوکيدارانو کوټې جوړې شوې وې چې د هرې يوې اوږدوالے او پلنوالے لس نيم فټه وو او د څوکيدارانو د کوټو په مينځ کښې د دېوال پلنوالے پاو کم نهۀ فټه وو. او د څوکيدارانو د کوټو شاته د تېرېدو لاره وه چې لس نيم فټه ژوره وه او د دې کمرو نه وروستو يوه بله درشل وه چې لس نيم فټه وه او د مالِک خُدائ کور ته تللې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20370, 'Ezekiel 40:8', 'Ezekiel', 40, 8, '&nbsp;نو بيا هغۀ د دروازې دننه ډيوډۍ ناپ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20371, 'Ezekiel 40:9', 'Ezekiel', 40, 9, '&nbsp;نو بيا د هغې اوږدوالے څوارلس فټه وو او د هغې د ستنې پلنوالے درې نيم فټه وو. د دې ډيوډۍ آخر سر د خُدائ پاک د کور د داخلېدو دواړو خواؤ دېوالونو ته نزدې او مخامخ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20372, 'Ezekiel 40:10', 'Ezekiel', 40, 10, '&nbsp;د مشرق خوا ته دروازه کښې په دواړو طرفونو ته درې کوټې وې، او ټولې په يو ناپ تول وې او د دې په مينځ کښې ټول دېوالونه هم يو شان پلن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20373, 'Ezekiel 40:11', 'Ezekiel', 40, 11, '&nbsp;نو بيا هغۀ د دروازې سره د داخلېدو د ځائ پلنوالے ناپ کړو، کوم چې اوولس نيم فټه پلن وو او د دروازې سره لاره پاو کم درويشت فټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20374, 'Ezekiel 40:12', 'Ezekiel', 40, 12, '&nbsp;د څوکيدارانو د هرې کوټې مخکښې يو دېوال وو چې يوويشت اِنچه وو او د هرې کمرې اوږدوالے او پلنوالے لس نيم فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20375, 'Ezekiel 40:13', 'Ezekiel', 40, 13, '&nbsp;نو بيا هغۀ په دې دروازه د څوکيدار د کوټې د شا د دېوال نه واخله د مخامخ کوټې د شا د دېوال پورې فاصله ناپ کړه، هغه پاو کم څلور څلوېښت فټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20376, 'Ezekiel 40:14', 'Ezekiel', 40, 14, '&nbsp;هغۀ بيا د دروازې مينځنے دېوال کوم چې د خُدائ د کور دربار سره يوځائ شوے وو ناپ کړو هغه يو سل او پينځۀ فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20377, 'Ezekiel 40:15', 'Ezekiel', 40, 15, '&nbsp;د دروازې د داخلېدو نه واخله د دربار تر آخر سر پورې فاصله اووۀ اتيا نيم فټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20378, 'Ezekiel 40:16', 'Ezekiel', 40, 16, '&nbsp;د څوکيدارانو په ټولو کوټو کښې وړې وړې کړکۍ غوندې وې، څۀ په بهرنى دېوالونو کښې وې، څۀ د کمرو په دننه دېوالونو کښې وې. او په دېوالونو د کجورو د ونو ګُلکارى شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20379, 'Ezekiel 40:17', 'Ezekiel', 40, 17, '&nbsp;نو بيا هغۀ زۀ د دروازې په لار د خُدائ د کور بهرنى دربار ته راوستلم. هلته ما يو څو کوټې او پياده لاره وليدله چې د دربار نه ګېرچاپېره راتاو شوې وه او دې لار ته مخامخ دېرش کوټې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20380, 'Ezekiel 40:18', 'Ezekiel', 40, 18, '&nbsp;دا پخه لار تر دروازو پورې جوړه شوې وه او د دېوالونو نه تر دربار پورې غزېدلې وه او هم دومره فاصله يې د عمومى دروازې پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20381, 'Ezekiel 40:19', 'Ezekiel', 40, 19, '&nbsp;نو بيا هغۀ د دننه نه د ښکته دروازې د دربار داخل نه بهر طرف ته فاصله ناپ کړه، دا د مشرق خوا ته يو سل او پينځۀ اويا فټه او شمال خوا ته هم يو شان فاصله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20382, 'Ezekiel 40:20', 'Ezekiel', 40, 20, '&nbsp;نو بيا هغۀ شمال خوا ته د دروازې اوږدوالے او پلنوالے ناپ کړو، کوم چې بهر صحن طرف ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20383, 'Ezekiel 40:21', 'Ezekiel', 40, 21, '&nbsp;د دروازې د داخلېدو په لار کښې دواړو خواو د څوکيدارانو درې درې کوټې وې، د هغوئ په مينځ کښې دېوالونه او د هغوئ دننه کوټې ټولې د هغې وړومبې مشرقى دروازې په اندازه وې. د دروازې ډيوډۍ اووۀ اتيا نيم فټه اوږده وه او پاو کم څلور څلوېښت فټه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20384, 'Ezekiel 40:22', 'Ezekiel', 40, 22, '&nbsp;د مشرق دروازې په شان، د هغې د داخلېدو کوټه او کړکۍ او د کجورو د ونو ګُلکارى هم هغه شان په يوه اندازه شوې وې. او اووۀ پوړۍ هم ورته ختلې وې، چې مخامخ ورته ډيوډۍ وه چې دربار ته تللې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20385, 'Ezekiel 40:23', 'Ezekiel', 40, 23, '&nbsp;هلته دننه د دربار طرف چې د شمال خوا نه يوه دروازه وه، بلکل لکه د هغه دروازې په شان لکه څنګه چې په مشرق کښې وه. هغۀ د يوې دروازې بلې دروازې ته مخامخ فاصله ناپ کړه، هغه يو سل او پينځۀ اويا فټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20386, 'Ezekiel 40:24', 'Ezekiel', 40, 24, '&nbsp;نو بيا هغه سړى زۀ د جنوب خوا ته بوتلم او ما بيا هلته يوه دروازه وليده چې د جنوب خوا ته يې مخ وو. هغۀ بيا د دې دېوالونه او کوټې ناپ کړې چې بلکل د هغه نورو دروازو په ناپ تول وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20387, 'Ezekiel 40:25', 'Ezekiel', 40, 25, '&nbsp;د دروازې او د هغې د چوکيدارانو د کوټو ګېرچاپېره وړې وړې کړکۍ وې، د هغې کړکۍ د نورو کړکو په شان وې. د تېرېدو لار اووۀ اتيا نيم فټه اوږده وه او پاو کم څلور څلوېښت فټه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20388, 'Ezekiel 40:26', 'Ezekiel', 40, 26, '&nbsp;د هغه کوټو مخامخ هغې ته د بهر نه يوه لار ورختلې وه چې اووۀ پوړۍ يې وې، او د هغې په دېوالونو باندې په دواړو خواؤ د کجورو د ونو ګُلکارى شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20389, 'Ezekiel 40:27', 'Ezekiel', 40, 27, '&nbsp;د دننه دربار هم يوه دروازه وه چې جنوب خوا ته يې مخ وو، او هغۀ بيا د دې دروازې نه د بهر د جنوب دروازې خوا ته ناپ تول وکړو، هغه يو سل او پينځۀ اويا فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20390, 'Ezekiel 40:28', 'Ezekiel', 40, 28, '&nbsp;نو بيا هغه سړى زۀ دننه دربار ته په جنوبى دروازه باندې راوستلم، او هغۀ جنوبى دروازه ناپ کړه، هغه هم د نورو دروازو په ناپ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20391, 'Ezekiel 40:29', 'Ezekiel', 40, 29, '&nbsp;د هغې د څوکيدارانو کوټې، او مينځنى دېوالونه او ډيوډۍ د هغه نورو دروازو سره په ناپ کښې يو شان وې. دروازه او د هغې د کوټو کړکۍ ګېرچاپېره وې، هغه اووۀ اتيا نيم فټه اوږدې او پاو کم څلور څلوېښت فټه پلنې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20392, 'Ezekiel 40:30', 'Ezekiel', 40, 30, '&nbsp;د دروازې د داخلېدو د کوټې ناپ تول کومه چې دننه د دربار صحن ته ورغلې وه څوارلس فټه اوږده او پاو کم څلور څلوېښت فټه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20393, 'Ezekiel 40:31', 'Ezekiel', 40, 31, '&nbsp;د هغې د کوټې مخ بهر دربار خوا ته وو، د هغې په ستنو د کجورو د ونو ګُلکارى شوې وه، او اتۀ پوړۍ ورته ورختلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20394, 'Ezekiel 40:32', 'Ezekiel', 40, 32, '&nbsp;نو بيا هغۀ زۀ په مشرقى لار دننه دربار ته راوستلم، او هغۀ هغه دروازه ناپ کړه، د هغې ناپ هم د نورو سره يو شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20395, 'Ezekiel 40:33', 'Ezekiel', 40, 33, '&nbsp;د هغې د څوکيدارانو کوټې، مينځنى دېوالونه او د هغې ډيوډۍ د نورو دروازو سره يو شان په يو ناپ وې. د دروازې او د برنډې يو شان ګېرچاپېره کړکۍ وې. دا اووۀ اتيا نيم فټه اوږدې وې او پاو کم څلور څلوېښت فټه پلنې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20396, 'Ezekiel 40:34', 'Ezekiel', 40, 34, '&nbsp;د هغې د ډيوډۍ مخ دننه د دربار طرف ته وو، او د دواړو طرفو په ستنو يې د کجورو د ونو ګُلکارى شوې وه، او اتۀ پوړۍ ورختلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20397, 'Ezekiel 40:35', 'Ezekiel', 40, 35, '&nbsp;نو بيا هغۀ زۀ د شمال دروازې طرف ته راوستلم او هغۀ د هغې ناپ واخستو. او هغه لار هم د هغه نورو په شان په يو ناپ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20398, 'Ezekiel 40:36', 'Ezekiel', 40, 36, '&nbsp;د هغې د څوکيدارانو کوټې، مينځنى دېوالونه او د هغې ډيوډۍ د نورو دروازو سره يو شان په يو ناپ وې. د دروازې او برنډې يو شان ګېرچاپېره کړکۍ وې. دا اووۀ اتيا نيم فټه اوږدې وې او پاو کم څلور څلوېښت فټه پلنې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20399, 'Ezekiel 40:37', 'Ezekiel', 40, 37, '&nbsp;ډيوډۍ بهرنى دربار ته مخامخ وه. د تېرېدو د ځائ په دېوالونو باندې د کجورو د ونو ګُلکارى شوې وه. دې دروازې ته اتۀ پوړۍ ختلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20400, 'Ezekiel 40:38', 'Ezekiel', 40, 38, '&nbsp;د شمال د طرف نه دننه يوه دروازه وه چې د داخلېدو د کوټې د لارې نه دننه دربار ته تللې وه چې هلته به په هغې کښې د سوزولو قربانۍ څاروى وينځلے کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');